206	async function observeContext(project: LoadedProject): Promise<ContextObservation> {
207	  const config = await readGuardedText(project.root, project.configPath, {
208	    maxBytes: MAX_CONTEXT_DOCUMENT_BYTES,
209	    rejectHardLinks: true,
210	  });
211	  let totalBytes = config.bytes.byteLength;
212	  if (config.text !== project.configSource) {
213	    throw issueError(
214	      "E_CONCURRENT_MODIFICATION",
215	      "Configuration changed after the project was loaded.",
216	    );
217	  }
218	  const documents = new Map<string, GuardedTextRead>();
219	  for (const document of project.config.documents) {
220	    const filePath = resolveProjectPath(project.root, contextPath(document.path));
221	    const read = await readGuardedText(project.root, filePath, {
222	      maxBytes: MAX_CONTEXT_DOCUMENT_BYTES,
223	      rejectHardLinks: true,
224	    });
225	    totalBytes += read.bytes.byteLength;
226	    if (totalBytes > MAX_CANONICAL_CONTEXT_BYTES) {
227	      throw issueError(
228	        "E_CONTEXT_AGGREGATE_TOO_LARGE",
229	        `Portable resume context exceeds the ${MAX_CANONICAL_CONTEXT_BYTES}-byte aggregate read limit.`,
230	        "Reduce or split large context documents before resuming.",
231	      );
232	    }
233	    documents.set(document.id, read);
234	  }
235	  return { config, documents };
236	}
237	
238	function sameObservation(left: ContextObservation, right: ContextObservation): boolean {
239	  if (!sameGuardedRead(left.config, right.config)) return false;
240	  if (left.documents.size !== right.documents.size) return false;
241	  for (const [id, read] of left.documents) {
242	    const other = right.documents.get(id);
243	    if (other === undefined || !sameGuardedRead(read, other)) return false;
244	  }
245	  return true;
246	}
247	
248	function sameGuardedRead(left: GuardedTextRead, right: GuardedTextRead): boolean {
249	  return (
250	    left.bytes.equals(right.bytes) &&
251	    left.metadata.device === right.metadata.device &&
252	    left.metadata.inode === right.metadata.inode &&
253	    left.metadata.size === right.metadata.size &&
254	    left.metadata.mtimeNs === right.metadata.mtimeNs &&
255	    left.metadata.ctimeNs === right.metadata.ctimeNs &&
256	    left.metadata.linkCount === right.metadata.linkCount
257	  );
258	}
